items.example:
/* Valore di default */
.box { width: 100%; }

/* Da 768px */
@media (min-width: 768px) {
  .box { width: 400px; }
}

/* questo div è nascosto su schermi minori di 520 px */
@media (max-width: 520px) {
  div.example {
    display: none;
  }
}

