blocks.text:
/* Valore di default */
h1 { font-size: 2rem; }

/* Da 48rem (768px) */
@media (width >= 48rem) {
  h1 { font-size: 3rem; }
}

/* Da 80rem (1280px) */
@media (width >= 80rem) {
  h1 { font-size: 5rem; }
}

/* Soglie crescenti: a 90rem vince 5rem */
@media (width >= 48rem) {
  h1 { font-size: 3rem; }
}
@media (width >= 80rem) {
  h1 { font-size: 5rem; }
}

/* Ordine invertito: a 90rem vince 3rem */
@media (width >= 80rem) {
  h1 { font-size: 5rem; }
}
@media (width >= 48rem) {
  h1 { font-size: 3rem; }
}

/* Forma estesa */
h1 { font-size: 2rem; }

@media (width >= 48rem) {
  h1 { font-size: 3rem; }
}
@media (width >= 80rem) {
  h1 { font-size: 5rem; }
}

/* Con CSS nesting */
h1 {
  font-size: 2rem;

  @media (width >= 48rem) {
    font-size: 3rem;
  }
  @media (width >= 80rem) {
    font-size: 5rem;
  }
}

